/**
 * #3766 (CC 2.1.246): a subagent that stops at its maxTurns limit is reported
 * as PARTIAL, with a summary shaped
 *   "stopped at its N-turn limit (partial result; continue it with SendMessage to the task-id)"
 * The retry handler must (a) classify it as partial, not success, (b) name the
 * limit and the agent id, (c) point at SendMessage continuation, and (d) never
 * suggest a re-spawn. The verbatim summary text comes from the 2.1.251 binary's
 * subagent summary template.
 */

import { describe, test, expect, vi } from 'vitest';
import { mockCommonBasic } from '../fixtures/mock-common.js';

vi.mock('../../lib/common.js', () => mockCommonBasic({}));
vi.mock('node:fs', () => ({
  existsSync: vi.fn(() => false),
  readFileSync: vi.fn(() => ''),
  writeFileSync: vi.fn(),
  mkdirSync: vi.fn(),
}));

import { retryHandler, detectTurnLimit } from '../../subagent-stop/retry-handler.js';
import type { HookInput } from '../../types.js';

const TURN_LIMIT_SUMMARY =
  'Agent ork:code-quality-reviewer stopped at its 25-turn limit (partial result; continue it with SendMessage to the task-id). ' +
  'Reviewed 6 of 9 files so far; findings below.';

function input(overrides: Record<string, unknown> = {}): HookInput {
  return {
    hook_event_name: 'SubagentStop',
    session_id: 's-1',
    agent_id: 'a-7f3c',
    agent_type: 'ork:code-quality-reviewer',
    agent_transcript_path: '/tmp/none.jsonl',
    agent_output: TURN_LIMIT_SUMMARY,
    ...overrides,
  } as unknown as HookInput;
}

describe('detectTurnLimit', () => {
  test('reads the limit out of the 2.1.246 summary shape', () => {
    expect(detectTurnLimit(input())).toBe('25');
  });
  test('also matches the older "reached maximum number of turns" phrasing', () => {
    expect(detectTurnLimit(input({ agent_output: 'Reached maximum number of turns (40). Stopping.' }))).toBe('40');
  });
  test('returns null for an ordinary completion', () => {
    expect(detectTurnLimit(input({ agent_output: 'Done. All 9 files reviewed, no findings.' }))).toBeNull();
  });
  test('never throws on a payload without output', () => {
    expect(detectTurnLimit({ hook_event_name: 'SubagentStop' } as unknown as HookInput)).toBeNull();
  });
});

describe('retryHandler on a maxTurns partial (CC 2.1.246, #3766)', () => {
  test('tags the result partial, names the limit and the agent id, and points at SendMessage', () => {
    const r = retryHandler(input());
    expect(r.continue).toBe(true);
    const ctx = r.hookSpecificOutput?.additionalContext ?? '';
    expect(ctx).toContain('[PARTIAL RESULT]');
    expect(ctx).toContain('25-turn limit');
    expect(ctx).toContain('a-7f3c');
    expect(ctx).toContain('SendMessage');
    expect(ctx).toMatch(/Do NOT re-spawn/i);
    expect(ctx).not.toContain('killed or timed out');
  });

  test('falls back to the generic partial message when no id is present', () => {
    const r = retryHandler(input({ agent_id: undefined }));
    const ctx = r.hookSpecificOutput?.additionalContext ?? '';
    expect(ctx).toContain('task id from the completion notice');
  });

  test('a killed/timeout partial keeps the pre-2.1.246 message', () => {
    const r = retryHandler(input({ agent_output: 'I completed the task partially but some parts failed' }));
    const ctx = r.hookSpecificOutput?.additionalContext ?? '';
    expect(ctx).toContain('killed or timed out');
    expect(ctx).not.toContain('turn limit');
  });
});
